/**
 * Shapes and constants traced from the vector ROM and object tables of the
 * original 1983 Atari Star Wars arcade game. Data only: no code from the
 * original is reproduced. Regenerated by hand from the object tables; do not
 * edit the numbers by hand.
 *
 * 3-D models are in the original's model frame (+X forward, +Y right, +Z up,
 * left-handed) in "model units"; multiply by `scale` for the size the
 * original's maths used, and by 2 again for the world-unit size (see
 * docs/reference/projection.md). Convert to Three.js with (x, y, z) -> (y, z, -x).
 *
 * 2-D pictures are in vector-generator screen units, +X right, +Y up.
 */

export interface RomModel {
  /** Model-unit vertices as written in the object table; index 0 is the centre. */
  readonly points: readonly (readonly [number, number, number])[];
  /** Assembly-time scale factor applied to every point. */
  readonly scale: number;
  /** Pairs of point indices joined by a visible line, in draw order. */
  readonly lines: readonly (readonly [number, number])[];
}

export type Polyline = readonly (readonly [number, number])[];

